return items.map(item => {
  const salida = String(item.json.output ?? '');
  const texto = salida.toLowerCase();

  const horarioInvalido =
    texto.includes('hora de finalización debe ser posterior') ||
    texto.includes('horafin debe ser posterior') ||
    texto.includes('hora final debe ser posterior');

  if (horarioInvalido) {
    item.json.output =
      'La hora de finalización debe ser posterior a la hora de inicio. ' +
      'Por favor, indique un horario válido.';
  }

  return item;
});
